@@ -1513,0 +1512,17 @@
+
+                // ====================================================================
+                // 辅助方法：从批量数据字典中获取数据或返回空列表
+                // ====================================================================
+                /// <summary>
+                /// 从批量数据字典中获取数据或返回空列表（降低认知复杂度）
+                /// </summary>
+                private List<T> GetBatchDataOrEmpty<T>(Dictionary<int, List<T>> batchData, int key) where T : class
+                {
+                    if (batchData == null)
+                        return new List<T>();
+
+                    if (batchData.TryGetValue(key, out var result))
+                        return result;
+
+                    return new List<T>();
+                }

